comp.js文件是一个web components的定义，子应用动态加载这个js，无法正常渲染（子应用单独打开可以渲染）

import { useEffect } from 'react'
function App() {
  useEffect(() => {
    const s = document.createElement('script')
    s.src = '/comp.js'
    document.body.appendChild(s)
  }, [])

  return (
      < div>
        < my-button>按钮组件</ my-button>
      </ div>
  )
}
export default App

